def clean(s): return re.sub(r'\s*—\s*',', ',s).replace('–','-')
# only hero autoloads; others lazy (data-src, loaded by IntersectionObserver)
def lazy(n): return f'<video class="lz" muted loop playsinline preload="none" poster="{C}{n}.jpg" style="background:url({C}{n}.jpg) center/cover" data-m="{C}{n}-960.mp4" data-w="{C}{n}-1920.webm" data-d="{C}{n}-1920.mp4"></video>'
def still(n): return f'<img class="ph" loading="lazy" src="{C}{n}.jpg" alt="">'
LZ='<script>const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const v=e.target;io.unobserve(v);[["(max-width:768px)",v.dataset.m,"video/mp4"],["",v.dataset.w,"video/webm"],["",v.dataset.d,"video/mp4"]].forEach(([m,s,t])=>{const x=document.createElement("source");if(m)x.media=m;x.src=s;x.type=t;v.append(x)});v.load();if(!matchMedia("(prefers-reduced-motion: reduce)").matches)v.play().catch(()=>{})}),{rootMargin:"200px"});document.querySelectorAll("video.lz").forEach(v=>io.observe(v));if(matchMedia("(prefers-reduced-motion: reduce)").matches)document.querySelectorAll("video[autoplay]").forEach(v=>{v.removeAttribute("autoplay");v.pause()})</script>'
